queries.sparql:
SELECT ?item ?itemLabel ?labelPt ?date ?typeLabel ?sitelinks
WHERE {
  {
    SELECT ?item (MIN(?when) AS ?date) WHERE {
      VALUES ?class { wd:Q40231 }
      VALUES ?where { wd:Q45 wd:Q916 wd:Q1029 wd:Q1011 wd:Q1039 wd:Q1006 wd:Q574 wd:Q14773 }
      ?item wdt:P31/wdt:P279* ?class .
      ?item (wdt:P17|wdt:P276|wdt:P710) ?where .
      ?item (wdt:P585|wdt:P580) ?when .
      ?item wikibase:sitelinks ?links . FILTER(?links >= 2)
      FILTER(?when >= "1890-01-01T00:00:00Z"^^xsd:dateTime && ?when < "1900-01-01T00:00:00Z"^^xsd:dateTime)
    }
    GROUP BY ?item
    ORDER BY ?date
    LIMIT 200
  }
  OPTIONAL { ?item wikibase:sitelinks ?sitelinks }
  OPTIONAL { ?item rdfs:label ?itemLabel . FILTER(LANG(?itemLabel) = "en") }
  OPTIONAL { ?item rdfs:label ?labelPt . FILTER(LANG(?labelPt) = "pt") }
  OPTIONAL { ?item wdt:P31 ?c . ?c rdfs:label ?typeLabel . FILTER(LANG(?typeLabel) = "en") }
}
ORDER BY ?date

